<script setup>
import { computed, ref } from 'vue'
import { usePage } from '@inertiajs/vue3'
import AdminLayout from '../../AdminLayout.vue'

defineOptions({ layout: AdminLayout })
const props = defineProps({
  portal: { type: Object, required: true }, tab: { type: String, required: true }, info: { type: Object, required: true },
  alerts: { type: Array, required: true }, supportEvents: { type: Array, required: true }, pendingForPortal: { type: Number, required: true },
  tableCount: { type: [Number, null], default: null }, dbError: { type: String, default: null }, packages: { type: Array, default: () => [] },
  payments: { type: Array, default: () => [] }, charges: { type: Array, default: () => [] }, extras: { type: Object, default: () => ({ one_time: 0, cycle: 0 }) },
  quotes: { type: Object, default: () => ({}) }, summary: { type: Object, default: () => ({}) }, logs: { type: Object, default: () => ({ data: [], links: [] }) },
  ranges: { type: Object, default: () => ({}) }, filters: { type: Object, default: () => ({}) }, portalUrls: { type: Object, required: true },
  requestsUrl: { type: String, required: true }, newApiToken: { type: String, default: null },
})
const page = usePage()
const csrf = page.props.adminLayout.csrfToken
const subscription = computed(() => props.info.subscription)
const stateTone = computed(() => ({ active: 'success', grace: 'warning', expired: 'danger' }[props.info.state] || 'secondary'))
const defaultPackageId = computed(() => subscription.value?.package_id ?? props.packages.find((p) => p.slug === 'package-1')?.id)
const selectedPackageId = ref('')
const advanceMonths = ref(0)
const amount = ref('')
const copyMessage = ref('')
const currentPackage = computed(() => props.packages.find((p) => String(p.id) === String(selectedPackageId.value || defaultPackageId.value)) || props.packages[0])
const quote = computed(() => currentPackage.value ? props.quotes[currentPackage.value.id] || { due: 0, remaining: 0 } : { due: 0, remaining: 0 })
const maxAdvance = computed(() => Math.max(0, Number(quote.value.remaining || 0) - Number(quote.value.due || 0)))
const payableMonths = computed(() => Number(quote.value.due || 0) + Number(advanceMonths.value || 0))
const updatePaymentAmount = () => {
  if (!currentPackage.value) return
  const price = Number(currentPackage.value.price || 0)
  const extra = currentPackage.value.is_trial ? 0 : Number(props.extras.one_time || 0) + Number(props.extras.cycle || 0) * payableMonths.value
  amount.value = String(Math.round(price * payableMonths.value + extra))
}
const portalTabUrl = (tab) => `${props.portalUrls.show}?tab=${tab}`
const removeChargeUrl = (id) => `${props.portalUrls.charges}/${id}`
const money = (value, decimals = 0) => Number(value || 0).toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals })
const dateLabel = (value) => value ? new Date(value).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : '—'
const statusTone = (status) => status >= 500 ? 'danger' : status >= 400 ? 'warning' : status >= 300 ? 'info' : 'success'
async function copyApiToken() {
  const input = document.getElementById('newApiToken')
  if (!input) return
  input.select()
  try { await navigator.clipboard.writeText(input.value) } catch { document.execCommand('copy') }
  copyMessage.value = 'Copied'
  window.setTimeout(() => { copyMessage.value = '' }, 1500)
}
if (currentPackage.value) updatePaymentAmount()
</script>

<template>
  <div class="d-flex flex-wrap justify-content-between align-items-start gap-3 mb-3"><div><a :href="portalUrls.index" class="fs-9">&larr; All portals</a><h3 class="mb-1 mt-1">{{ portal.portal_name }}</h3><div class="d-flex flex-wrap align-items-center gap-2"><span class="badge badge-phoenix" :class="portal.status === 'active' ? 'badge-phoenix-success' : 'badge-phoenix-danger'">{{ portal.status }}</span><span v-if="info.subscription" class="badge badge-phoenix" :class="`badge-phoenix-${stateTone}`">{{ info.subscription.package?.name }} · {{ info.state }}</span><span class="fs-9 text-body-tertiary">{{ portal.editor_mobile }} · {{ portal.database_name || 'no database' }}</span></div></div><div class="d-flex flex-wrap gap-2"><form v-if="portal.provisioned" method="POST" :action="portalUrls.supportStart" target="_blank" rel="noopener" data-confirm="Start an audited support session? You can submit purchase and grace-period requests, which still require approval."><input type="hidden" name="_token" :value="csrf"><button class="btn btn-phoenix-primary" type="submit">Log in as admin</button></form><form method="POST" :action="portalUrls.toggle" :data-confirm="portal.status === 'active' ? 'Suspend this portal? The editor will be blocked from logging in.' : null"><input type="hidden" name="_token" :value="csrf"><button class="btn" :class="portal.status === 'active' ? 'btn-warning' : 'btn-success'" type="submit">{{ portal.status === 'active' ? 'Suspend portal' : 'Activate portal' }}</button></form></div></div>

  <ul class="nav nav-tabs mb-4"><li class="nav-item"><a class="nav-link" :class="{ active: tab === 'overview' }" :href="portalTabUrl('overview')">Overview</a></li><li class="nav-item"><a class="nav-link" :class="{ active: tab === 'billing' }" :href="portalTabUrl('billing')">Billing <span v-if="info.due_months > 0" class="badge badge-phoenix badge-phoenix-warning ms-1">{{ info.due_months }} due</span></a></li><li class="nav-item"><a class="nav-link" :class="{ active: tab === 'activity' }" :href="portalTabUrl('activity')">Activity <span v-if="alerts.length" class="badge badge-phoenix badge-phoenix-danger ms-1">{{ alerts.length }}</span></a></li></ul>
  <div v-if="pendingForPortal > 0" class="alert alert-subtle-info d-flex flex-wrap justify-content-between align-items-center gap-2"><div>This portal has <b>{{ pendingForPortal }}</b> pending request(s) (grace period / renewal).</div><a class="btn btn-sm btn-phoenix-primary" :href="requestsUrl">Review requests</a></div>

  <div v-if="tab === 'overview'" class="row g-4">
    <div class="col-lg-7"><div class="card"><div class="card-body"><h5 class="mb-3">Portal information</h5><form method="POST" :action="portalUrls.update"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="PUT"><div class="row g-3"><div class="col-md-6"><label class="form-label">Portal name</label><input class="form-control" name="portal_name" :value="portal.portal_name" required></div><div class="col-md-6"><label class="form-label">Reg. no</label><input class="form-control" name="portal_reg_no" :value="portal.portal_reg_no || ''"></div><div class="col-md-6"><label class="form-label">Editor name</label><input class="form-control" name="editor_name" :value="portal.editor_name || ''"></div><div class="col-md-6"><label class="form-label">Editor email</label><input class="form-control" type="email" name="editor_email" :value="portal.editor_email || ''"></div><div class="col-md-6"><label class="form-label">Editor mobile</label><input class="form-control" name="editor_mobile" :value="portal.editor_mobile" required></div></div><button class="btn btn-primary mt-4" type="submit">Save changes</button></form></div></div>
      <div class="card mt-4"><div class="card-header"><h5 class="mb-0">Admin support audit</h5></div><div class="table-responsive"><table class="table table-hover mb-0 align-middle"><thead><tr><th>Admin</th><th>Action</th><th>Page</th><th>When</th></tr></thead><tbody><tr v-for="(event, i) in supportEvents" :key="i"><td>{{ event.admin_name }}</td><td>{{ event.action }}</td><td><code>{{ event.path || '—' }}</code></td><td class="fs-9">{{ event.created_at }}</td></tr><tr v-if="supportEvents.length === 0"><td colspan="4" class="text-center text-body-tertiary py-4">No admin support sessions yet.</td></tr></tbody></table></div></div>
    </div>
    <div class="col-lg-5"><div class="card mb-4"><div class="card-body"><h5 class="mb-3">Tenant database</h5><dl class="row mb-3"><dt class="col-5">Database</dt><dd class="col-7">{{ portal.database_name || '—' }}</dd><dt class="col-5">Provisioned</dt><dd class="col-7">{{ portal.provisioned_at || 'No' }}</dd><dt class="col-5">Tables</dt><dd class="col-7">{{ tableCount ?? '—' }}</dd><dt class="col-5">Created</dt><dd class="col-7">{{ portal.created_at }}</dd><dt class="col-5">Last login</dt><dd class="col-7">{{ portal.last_login_at }}</dd></dl><div v-if="dbError" class="alert alert-subtle-warning fs-9">DB connection error: {{ dbError }}</div><div v-if="portal.provision_error" class="alert alert-subtle-warning fs-9">Last provisioning error: {{ portal.provision_error }}</div><form method="POST" :action="portalUrls.provision"><input type="hidden" name="_token" :value="csrf"><button class="btn btn-phoenix-secondary" type="submit">Create / repair tenant database</button></form></div></div>
      <div class="card mb-4"><div class="card-body"><div class="d-flex align-items-center justify-content-between mb-1"><h5 class="mb-0">Public API token</h5><span class="badge badge-phoenix" :class="portal.has_api_token ? 'badge-phoenix-success' : 'badge-phoenix-secondary'">{{ portal.has_api_token ? 'Active' : 'Not created' }}</span></div><p class="fs-9 text-body-tertiary mb-3">Read-only access to this portal's database with a secret token.</p><div v-if="newApiToken" class="alert alert-subtle-warning p-3 mb-3"><div class="fs-9 fw-semibold mb-2">Copy now — this token is shown only once</div><div class="input-group input-group-sm mb-2"><input id="newApiToken" class="form-control font-monospace" :value="newApiToken" readonly @click="$event.target.select()"><button class="btn btn-phoenix-secondary" type="button" @click="copyApiToken">{{ copyMessage || 'Copy' }}</button></div></div><div v-if="portal.has_api_token" class="border rounded-2 px-3 py-2 mb-3 fs-9"><div class="d-flex justify-content-between py-1"><span class="text-body-tertiary">Token</span><span class="font-monospace">npk_…{{ portal.api_token_last4 }}</span></div><div class="d-flex justify-content-between py-1"><span class="text-body-tertiary">Created</span><span>{{ portal.api_token_created_at || '—' }}</span></div><div class="d-flex justify-content-between py-1"><span class="text-body-tertiary">Last used</span><span>{{ portal.api_token_last_used_at }}</span></div></div><p v-else class="fs-9 mb-3">No token yet, so the API is closed for this portal.</p><div class="d-flex flex-wrap gap-2"><form method="POST" :action="portalUrls.apiTokenIssue" :data-confirm="portal.has_api_token ? 'This replaces the current token. Anything using the old token stops working. Continue?' : null"><input type="hidden" name="_token" :value="csrf"><button class="btn btn-sm btn-phoenix-secondary" type="submit">{{ portal.has_api_token ? 'Regenerate token' : 'Create API token' }}</button></form><form v-if="portal.has_api_token" method="POST" :action="portalUrls.apiTokenRevoke" data-confirm="Revoke the token? The API closes for this portal."><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-phoenix-danger" type="submit">Revoke</button></form></div></div></div>
      <div class="card border-danger"><div class="card-body"><h5 class="mb-2 text-danger">Danger zone</h5><p class="fs-9 text-body-tertiary">Deleting removes the portal and drops its tenant database. This cannot be undone.</p><form method="POST" :action="portalUrls.destroy" data-confirm="This permanently deletes the portal AND its database. Continue?"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="DELETE"><button class="btn btn-danger" type="submit">Delete portal &amp; database</button></form></div></div>
    </div>
  </div>

  <div v-else-if="tab === 'billing'" class="row g-4">
    <div class="col-lg-4"><div class="card h-100"><div class="card-body"><h5 class="mb-3">Current plan</h5><template v-if="subscription"><div class="fs-6 fw-bold">{{ subscription.package?.name }}</div><span class="badge badge-phoenix mb-3" :class="`badge-phoenix-${stateTone}`">{{ info.state }}</span><dl class="row mb-0"><dt class="col-5">Term started</dt><dd class="col-7">{{ dateLabel(subscription.starts_at) }}</dd><dt class="col-5">Paid till</dt><dd class="col-7">{{ dateLabel(subscription.ends_at) }}</dd><template v-if="subscription.term_months > 1"><dt class="col-5">Months paid</dt><dd class="col-7">{{ subscription.paid_months }} / {{ subscription.term_months }}</dd></template><template v-if="info.state === 'active'"><dt class="col-5">Days left</dt><dd class="col-7">{{ info.days_left }}</dd></template><template v-else-if="info.state === 'grace'"><dt class="col-5">Grace left</dt><dd class="col-7 text-danger">{{ info.grace_days_left }} day(s) (till {{ dateLabel(info.grace_ends_at) }})</dd></template><template v-else-if="info.state === 'expired'"><dt class="col-5">Blocked since</dt><dd class="col-7 text-danger">{{ dateLabel(info.grace_ends_at) }}</dd></template><template v-if="info.due_months > 0"><dt class="col-5">Dues</dt><dd class="col-7 text-danger fw-bold">{{ info.due_months }} month(s) = {{ money(info.due_months * subscription.price) }} tk</dd></template></dl></template><p v-else class="text-body-tertiary mb-0">No subscription yet. The trial starts automatically on the portal's first login, or record a payment here.</p></div></div></div>
    <div class="col-lg-8"><div class="card h-100"><div class="card-body"><h5 class="mb-3">Record payment</h5><form method="POST" :action="portalUrls.payment"><input type="hidden" name="_token" :value="csrf"><div class="row g-3"><div class="col-md-5"><label class="form-label">Package</label><select class="form-select" name="package_id" :value="selectedPackageId || defaultPackageId" @change="selectedPackageId = $event.target.value; advanceMonths = 0; updatePaymentAmount()"><option v-for="pkg in packages" :key="pkg.id" :value="pkg.id">{{ pkg.name }} – {{ money(pkg.price) }} tk/{{ pkg.is_trial ? `${pkg.duration_days} days` : 'month' }}{{ pkg.term_months > 1 ? ` · ${pkg.term_months} month term` : '' }}</option></select></div><div class="col-md-3"><label class="form-label">Advance months</label><input class="form-control" type="number" min="0" :max="maxAdvance" name="advance_months" v-model.number="advanceMonths" @input="updatePaymentAmount"><div class="form-text">Due: {{ quote.due }} month(s) · paying {{ payableMonths }} · max advance {{ maxAdvance }}</div></div><div class="col-md-4"><label class="form-label">Amount received (tk)</label><input class="form-control" type="number" step="0.01" min="0" name="amount" v-model="amount" required><div v-if="extras.one_time > 0 || extras.cycle > 0" class="form-text">Includes additional charges ({{ money(extras.one_time) }} one-time + {{ money(extras.cycle) }}/month)</div></div><div class="col-md-3"><label class="form-label">Method</label><select class="form-select" name="method"><option value="cash">Cash</option><option value="bkash">bKash</option><option value="nagad">Nagad</option><option value="rocket">Rocket</option><option value="bank">Bank</option><option value="other">Other</option></select></div><div class="col-md-3"><label class="form-label">Trx ID <span class="text-body-tertiary">(optional)</span></label><input class="form-control" name="trx_id"></div><div class="col-md-6"><label class="form-label">Note <span class="text-body-tertiary">(optional)</span></label><input class="form-control" name="note"></div></div><button class="btn btn-primary mt-3" type="submit">Save payment</button><div class="form-text mt-2">Any skipped month is already counted in "due" and is paid together with this month. Early payment extends the paid period without losing days.</div></form></div></div></div>
    <div class="col-lg-6"><div class="card h-100"><div class="card-body"><h5 class="mb-3">Additional charges</h5><form method="POST" :action="portalUrls.charges" class="row g-2 mb-3"><input type="hidden" name="_token" :value="csrf"><div class="col-md-5"><input class="form-control" name="purpose" placeholder="Purpose (e.g. setup fee)" required></div><div class="col-md-3"><input class="form-control" type="number" min="1" step="0.01" name="amount" placeholder="Amount" required></div><div class="col-md-2"><select class="form-select" name="type"><option value="one_time">One time</option><option value="cycle">Every month</option></select></div><div class="col-md-2"><button class="btn btn-phoenix-primary w-100" type="submit">Add</button></div></form><table class="table table-sm mb-0"><thead><tr><th>Purpose</th><th>Amount</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="charge in charges" :key="charge.id"><td>{{ charge.purpose }}</td><td>{{ money(charge.amount) }}</td><td>{{ charge.type === 'cycle' ? 'Every month' : 'One time' }}</td><td><span class="badge badge-phoenix" :class="charge.type === 'one_time' && charge.paid_at ? 'badge-phoenix-success' : 'badge-phoenix-warning'">{{ charge.type === 'one_time' && charge.paid_at ? 'paid' : 'due' }}</span></td><td class="text-end"><form method="POST" :action="removeChargeUrl(charge.id)" data-confirm="Remove this charge?"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-link text-danger p-0" type="submit">remove</button></form></td></tr><tr v-if="charges.length === 0"><td colspan="5" class="text-body-tertiary">None</td></tr></tbody></table></div></div></div>
    <div class="col-lg-6"><div class="card h-100"><div class="card-body"><h5 class="mb-3">Payment history</h5><table class="table table-sm mb-0"><thead><tr><th>Date</th><th>Package</th><th>Months</th><th>Amount</th><th>Method</th><th>Trx</th></tr></thead><tbody><tr v-for="payment in payments" :key="payment.id"><td>{{ dateLabel(payment.paid_at) }}</td><td>{{ payment.package?.name || '—' }}</td><td>{{ payment.months }}</td><td>{{ money(payment.amount) }}</td><td>{{ payment.method.charAt(0).toUpperCase() + payment.method.slice(1) }}</td><td>{{ payment.trx_id || '—' }}</td></tr><tr v-if="payments.length === 0"><td colspan="6" class="text-body-tertiary">No payments yet</td></tr></tbody></table></div></div></div>
  </div>

  <div v-else>
    <div v-if="alerts.length" class="alert mb-3" :class="alerts.some((a) => a.level === 'danger') ? 'alert-subtle-danger' : 'alert-subtle-warning'"><div class="d-flex flex-wrap justify-content-between align-items-start gap-3"><div><div class="fw-bold mb-1">Suspicious activity detected</div><div v-for="(alert, i) in alerts" :key="i">• {{ alert.message }}</div></div><form v-if="portal.status === 'active'" method="POST" :action="portalUrls.toggle" :data-confirm="`Suspend ${portal.portal_name}? The editor will be blocked from logging in.`"><input type="hidden" name="_token" :value="csrf"><button class="btn btn-danger" type="submit">Suspend portal</button></form></div></div><div v-else class="alert alert-subtle-success mb-3">No suspicious patterns detected in the last hour.</div>
    <div class="row g-3 mb-4"><div v-for="[label, value] in [['Requests', summary.requests], ['Errors', summary.errors], ['Unique IPs', summary.ips], ['DB writes', summary.writes], ['Avg response (ms)', summary.avg_ms]]" :key="label" class="col-6 col-xl"><div class="card"><div class="card-body py-3"><div class="stat-label">{{ label }}</div><div class="stat-value">{{ Number(value || 0).toLocaleString('en-US') }}</div></div></div></div></div>
    <div class="row g-3 mb-4"><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h6 class="mb-3">Most used endpoints</h6><table class="table table-sm mb-0"><thead><tr><th>Path</th><th>Hits</th><th>Errors</th></tr></thead><tbody><tr v-for="row in summary.top_paths" :key="row.path"><td class="path-cell">{{ row.path }}</td><td>{{ row.hits }}</td><td>{{ row.errors }}</td></tr><tr v-if="!summary.top_paths?.length"><td colspan="3" class="text-body-tertiary">No requests in this range.</td></tr></tbody></table></div></div></div><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h6 class="mb-3">IP addresses</h6><table class="table table-sm mb-0"><thead><tr><th>IP</th><th>Hits</th><th>Last seen</th></tr></thead><tbody><tr v-for="row in summary.top_ips" :key="row.ip"><td>{{ row.ip }}</td><td>{{ row.hits }}</td><td class="fs-9">{{ dateLabel(row.last_seen) }}</td></tr><tr v-if="!summary.top_ips?.length"><td colspan="3" class="text-body-tertiary">No requests in this range.</td></tr></tbody></table></div></div></div></div>
    <form method="GET" :action="portalUrls.show" class="row g-2 mb-3 align-items-end"><input type="hidden" name="tab" value="activity"><div class="col-md-3"><select class="form-select" name="range" :value="filters.range || '24h'" @change="$event.target.form.requestSubmit()"><option v-for="(label, key) in ranges" :key="key" :value="key">{{ label }}</option></select></div><div class="col-md-3"><select class="form-select" name="event" :value="filters.event || ''" @change="$event.target.form.requestSubmit()"><option value="">All events</option><option value="request">Requests</option><option value="login">Logins</option><option value="login_blocked">Blocked logins</option></select></div><div class="col-md-3"><select class="form-select" name="status" :value="filters.status || ''" @change="$event.target.form.requestSubmit()"><option value="">Any status</option><option value="error">Errors (4xx + 5xx)</option><option value="2xx">2xx</option><option value="3xx">3xx</option><option value="4xx">4xx</option><option value="5xx">5xx</option></select></div><div class="col-md-2"><input class="form-control" type="search" name="q" :value="filters.q || ''" placeholder="Path or IP" autocomplete="off"></div><div class="col-auto"><button class="btn btn-primary" type="submit">Filter</button></div></form>
    <div class="card"><div class="table-responsive"><table class="table table-hover table-sm mb-0 align-middle"><thead><tr><th>Time</th><th>Method</th><th>Path</th><th>Status</th><th>IP</th><th title="Tenant DB queries / writes">DB q / w</th><th>ms</th></tr></thead><tbody><tr v-for="log in logs.data" :key="log.id" :title="log.user_agent"><td class="text-nowrap fs-9">{{ dateLabel(log.created_at) }}</td><td><code>{{ log.method }}</code></td><td class="path-cell"><span v-if="log.event === 'login'" class="badge badge-phoenix badge-phoenix-primary">login</span><span v-else-if="log.event === 'login_blocked'" class="badge badge-phoenix badge-phoenix-danger">login blocked</span> {{ log.path }}</td><td><span class="badge badge-phoenix" :class="`badge-phoenix-${statusTone(log.status)}`">{{ log.status }}</span></td><td class="fs-9">{{ log.ip }}</td><td class="fs-9">{{ log.db_queries }} / <span :class="{ 'fw-bold': log.db_writes > 0 }">{{ log.db_writes }}</span></td><td class="fs-9">{{ log.duration_ms }}</td></tr><tr v-if="logs.data.length === 0"><td colspan="7" class="text-center text-body-tertiary py-5">No activity found for this filter.</td></tr></tbody></table></div></div>
    <nav v-if="logs.last_page > 1" class="mt-3" aria-label="Portal activity pages"><ul class="pagination mb-0"><li v-for="(link, i) in logs.links" :key="i" class="page-item" :class="{ active: link.active, disabled: !link.url }"><a class="page-link" :href="link.url || '#'" v-html="link.label"></a></li></ul></nav>
  </div>
</template>
